Here is the root cause:
In ocfs2_info_freefrag_scan_chain(), when using the non-coherent path (ocfs2_read_blocks_sync()), the on-disk bg_bits value is used directly as the bitmap scan limit without validation. A crafted filesystem can set bg_bits to a value larger than the actual bitmap capacity, leading to an out-of-bounds memory access during bitmap walking.

Here is the patch:

 static int ocfs2_info_freefrag_scan_chain(struct ocfs2_super *osb,
 					  struct inode *gb_inode,
 					  struct ocfs2_dinode *gb_dinode,
 					  struct ocfs2_chain_rec *rec,
 					  struct ocfs2_info_freefrag *ffg,
 					  u32 chunks_in_group)
 {
 	int status = 0, used;
 	u64 blkno;

 	struct buffer_head *bh = NULL;
 	struct ocfs2_group_desc *bg = NULL;

-	unsigned int max_bits, num_clusters;
+	unsigned int max_bits, max_bitmap_bits, num_clusters;
 	unsigned int offset = 0, cluster, chunk;
 	unsigned int chunk_free, last_chunksize = 0;

 	if (!le32_to_cpu(rec->c_free))
 		goto bail;

+	max_bitmap_bits = 8 * ocfs2_group_bitmap_size(osb->sb, 0,
+					      osb->s_feature_incompat);
+
 	do {
 		if (!bg)
 			blkno = le64_to_cpu(rec->c_blkno);
 		else
 			blkno = le64_to_cpu(bg->bg_next_group);

 		if (bh) {
 			brelse(bh);
 			bh = NULL;
 		}

 		if (o2info_coherent(&ffg->iff_req))
 			status = ocfs2_read_group_descriptor(gb_inode,
 							     gb_dinode,
 							     blkno, &bh);
 		else
 			status = ocfs2_read_blocks_sync(osb, blkno, 1, &bh);

 		if (status < 0) {
 			mlog(ML_ERROR, "Can't read the group descriptor # "
 			     "%llu from device.", (unsigned long long)blkno);
 			status = -EIO;
 			goto bail;
 		}

 		bg = (struct ocfs2_group_desc *)bh->b_data;

 		if (!le16_to_cpu(bg->bg_free_bits_count))
 			continue;

 		max_bits = le16_to_cpu(bg->bg_bits);
+
+		/*
+		 * Non-coherent scans read raw blocks and do not get the
+		 * bg_bits validation from
+		 * ocfs2_read_group_descriptor().
+		 */
+		if (max_bits > max_bitmap_bits) {
+			mlog(ML_ERROR,
+			     "Group desc #%llu has %u bits, max bitmap bits %u\n",
+			     (unsigned long long)blkno, max_bits, max_bitmap_bits);
+			max_bits = max_bitmap_bits;
+		}
+
 		offset = 0;

 		for (chunk = 0; chunk < chunks_in_group; chunk++) {
 			/*
 			 * last chunk may be not an entire one.
 			 */
 			if ((offset + ffg->iff_chunksize) > max_bits)
 				num_clusters = max_bits - offset;
 			else
 				num_clusters = ffg->iff_chunksize;

 			chunk_free = 0;
 			for (cluster = 0; cluster < num_clusters; cluster++) {
 				used = ocfs2_test_bit(offset,
 						(unsigned long *)bg->bg_bitmap);
 				/*
 				 * - chunk_free counts free clusters in #N chunk.
 				 * - last_chunksize records the size(in) clusters
 				 *   for the last real free chunk being counted.
 				 */
 				if (!used) {
 					last_chunksize++;
 					chunk_free++;
 				}

 				if (used && last_chunksize) {
 					ocfs2_info_update_ffg(ffg,
 							      last_chunksize);
 					last_chunksize = 0;
 				}

 				offset++;
 			}

 			if (chunk_free == ffg->iff_chunksize)
 				ffg->iff_ffs.ffs_free_chunks++;
 		}

 		/*
 		 * need to update the info for last free chunk.
 		 */
 		if (last_chunksize)
 			ocfs2_info_update_ffg(ffg, last_chunksize);

 	} while (le64_to_cpu(bg->bg_next_group));

 bail:
 	brelse(bh);

 	return status;
 }



